    25:async function extractLabelText(file: File): Promise<string | null> {
    26:  // Try the experimental TextDetector API (Chrome on some platforms)
    27:  const TD = (window as unknown as { TextDetector?: new () => { detect: (img: ImageBitmap) => Promise<{ rawValue: string }[]> } }).TextDetector;
