    41:/**
    42: * Extract the most likely medication name and strength from raw OCR text.
    43: * Looks for patterns like "Paracetamol 500mg" or "Amlodipine 5 mg".
    44: */
    45:function parseLabelFields(text: string): { name: string; strength: string | null } {
    46:  const lines = text.split(/\n+/).map((l) => l.trim()).filter(Boolean);
    47:  // Try to find a line that looks like a medication name + strength
    48:  const medLine = lines.find((line) =>
    49:    /\d+\s*(?:mg|mcg|g|ml|iu)\b/i.test(line) || /^[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*$/.test(line),
    50:  );
    51:  if (medLine) {
    52:    const strengthMatch = medLine.match(/(\d+(?:\.\d+)?\s*(?:mg|mcg|g|ml|iu)\b)/i);
    53:    const strength = strengthMatch?.[1] ?? null;
    54:    const name = medLine.replace(strengthMatch?.[0] ?? "", "").trim() || medLine;
    55:    return { name: name.replace(/\s+/g, " "), strength };
    56:  }
    57:  // Fallback: use the first non-trivial line as the name
    58:  const firstLine = lines.find((l) => l.length >= 3 && l.length <= 60) ?? lines[0] ?? "";
    59:  const strengthMatch = firstLine.match(/(\d+(?:\.\d+)?\s*(?:mg|mcg|g|ml|iu)\b)/i);
    60:  return {
    61:    name: (strengthMatch ? firstLine.replace(strengthMatch[0], "") : firstLine).trim() || text.slice(0, 40),
    62:    strength: strengthMatch?.[1] ?? null,
    63:  };
    64:}
